        "en": "Even when the whole world tells you to move, it is your duty to plant yourself like a tree, look them in the eye and say, 'No, you move.'",
        "vi": "Ngay cả khi cả thế giới bảo bạn phải tránh đường, nhiệm vụ của bạn là bám rễ vững như một cái cây, nhìn thẳng vào mắt họ và nói: 'Không, các người mới phải tránh ra.'"
